import{_ as l,o as r,c as i,ag as s}from"./chunks/framework.RW_pGwXR.js";const o="/cours/assets/07-liste-deroulante.sKCEU8xP.png",n="/cours/assets/07-liste-deroulante-1.D-jKY6iW.png",t="data:image/png;base64,",a="/cours/assets/07-selection-toutes-cellules.QLn6ucQ1.png",c="/cours/assets/07-options%20mise-en-forme.CuwReX5G.png",u="/cours/assets/07-nouvelle-regle.BQxjHZml.png",d="/cours/assets/07-utiliser-une-formule.D6meB8LL.png",p="/cours/assets/07-surbrillance.CYdre_ZX.png",k=JSON.parse('{"title":"Mise en forme conditionnelle","description":"","frontmatter":{"title":"Mise en forme conditionnelle"},"headers":[],"relativePath":"modules/02-excel/07-mise-en-forme-cond.md","filePath":"modules/02-excel/07-mise-en-forme-cond.md"}'),m={name:"modules/02-excel/07-mise-en-forme-cond.md"};function g(h,e,f,A,v,x){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="mise-en-forme-conditionnelle" tabindex="-1">Mise en forme conditionnelle <a class="header-anchor" href="#mise-en-forme-conditionnelle" aria-label="Permalink to &quot;Mise en forme conditionnelle&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p><a href="https://livecegepfxgqc-my.sharepoint.com/:x:/g/personal/otremblay_cegepgarneau_ca/IQD2hGLn0VRtRqPzcce-dbgrAfT0j_iYCVzTVzHl8mvgX_s?e=u2PK9n" target="_blank" rel="noreferrer">07 – Mise en forme conditionnelle et validation des données</a></p><p>⚠️ Ne travaillez pas dans la version Excel du navigateur Web.</p><p><strong>Veuillez télécharger une copie de chaque exercice.</strong></p><ul><li>Fichier --&gt; Créer une copie --&gt; Télécharger une copie</li></ul><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><ul><li>Appliquer une mise en forme automatique selon des conditions</li><li>Mettre en évidence rapidement les données importantes</li><li>Visualiser les tendances et comparaisons dans les données</li><li>Contrôler la saisie de données avec la validation</li><li>Limiter les erreurs en utilisant des listes déroulantes et des règles de validation</li></ul><h2 id="validation-des-donnees" tabindex="-1">Validation des données <a class="header-anchor" href="#validation-des-donnees" aria-label="Permalink to &quot;Validation des données&quot;">​</a></h2><p>Limite les valeurs que l&#39;utilisateur peut entrer. Évite les erreurs de saisie.</p><p><strong>Types de validation :</strong></p><ul><li><strong>Listes déroulantes</strong> : l&#39;utilisateur choisit parmi des valeurs prédéfinies</li><li><strong>Plages numériques</strong> : accepte seulement les nombres dans une certaine plage (ex. : entre 0 et 100)</li><li><strong>Messages d&#39;erreur</strong> : affiche un message personnalisé si la saisie est invalide</li></ul><h3 id="exemple-creer-une-liste-deroulante" tabindex="-1">Exemple : créer une liste déroulante <a class="header-anchor" href="#exemple-creer-une-liste-deroulante" aria-label="Permalink to &quot;Exemple : créer une liste déroulante&quot;">​</a></h3><p><strong>Objectif :</strong> permettre à l&#39;utilisateur de choisir une catégorie (Fruits, Légumes, Viandes)</p><ol><li><p>Sélectionner les cellules où la liste déroulante doit apparaître</p></li><li><p>Aller à <strong>Données</strong> &gt; <strong>Validation des données</strong></p></li></ol><img src="'+o+'" alt="Menu Validation des données" class="img-bordered"><ol start="3"><li>Dans l&#39;onglet <strong>Paramètres</strong>, choisir <strong>Liste</strong> comme critère de validation</li></ol><img src="'+n+'" alt="Critère de validation : Liste" class="img-bordered"><ol start="4"><li><p>Entrer les valeurs séparées par des points-virgules : <code>Fruits;Légumes;Viandes</code> OU Sélectionner une plage avec votre souris.</p></li><li><p>Cocher <strong>Liste déroulante</strong> pour afficher la flèche</p></li><li><p>Valider</p></li></ol><img src="'+t+'" alt="Résultat avec liste déroulante" class="img-bordered"><blockquote><p>Les utilisateurs peuvent maintenant cliquer sur la flèche pour sélectionner une valeur, ou taper directement la valeur si elle existe dans la liste.</p></blockquote><h2 id="mise-en-forme-conditionnelle-1" tabindex="-1">Mise en forme conditionnelle <a class="header-anchor" href="#mise-en-forme-conditionnelle-1" aria-label="Permalink to &quot;Mise en forme conditionnelle&quot;">​</a></h2><p>La mise en forme conditionnelle applique automatiquement des styles (couleurs, barres, icônes) selon le contenu des cellules.</p><p><strong>Types de règles disponibles :</strong></p><ul><li><strong>Surbrillance</strong> : colore les cellules selon une condition simple (égal, supérieur, contient un texte, etc.)</li><li><strong>Valeurs de plage haute ou basse</strong> : identifie les n meilleures ou n pires valeurs</li><li><strong>Barre de données</strong> : affiche une barre proportionnelle à la valeur (visualisation rapide)</li><li><strong>Nuance de couleurs</strong> : crée un dégradé de couleurs selon la valeur (vert/jaune/rouge, par exemple)</li><li><strong>Jeux d&#39;icônes</strong> : affiche des icônes (flèches, feux, étoiles) selon le seuil</li></ul><h3 id="procedure" tabindex="-1">Procédure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procédure&quot;">​</a></h3><ol><li>Sélectionner la plage de données à formater</li><li>Aller à <strong>Accueil</strong> &gt; <strong>Mise en forme conditionnelle</strong></li><li>Choisir le type de règle : <ul><li>sélectionner une option prédéfinie OU</li><li><strong>Nouvelle règle</strong> : créer une règle personnalisée (approche recommandée)</li></ul></li><li>Définir les paramètres (condition, valeur seuil, format)</li><li>Appliquer et observer le résultat</li></ol><h3 id="exemple-de-format-personnalise" tabindex="-1">Exemple de format personnalisé <a class="header-anchor" href="#exemple-de-format-personnalise" aria-label="Permalink to &quot;Exemple de format personnalisé&quot;">​</a></h3><p><strong>Exemple – Mettre en rouge si le prix est plus élevé que 20k$ :</strong></p><ol><li>Sélectionner toutes les cellules qui pourraient être impactées par la mise en forme (toutes les données du tableau)</li></ol><img src="'+a+'" alt="Options de mise en forme conditionnelle" class="img-bordered"><ol start="2"><li>Aller à <strong>Accueil</strong> &gt; <strong>Mise en forme conditionnelle</strong> &gt; <strong>Gérer les règles</strong></li></ol><img src="'+c+'" alt="Options de mise en forme conditionnelle" class="img-bordered"><ol start="3"><li>Cliquer sur <strong>Nouvelle règle</strong></li></ol><img src="'+u+'" alt="Dialogue Nouvelle règle" class="img-bordered"><ol start="4"><li>Choisir la dernière option : <strong>Utiliser une formule pour déterminer les cellules à formater</strong></li></ol><img src="'+d+'" alt="Utiliser une formule" class="img-bordered"><ol start="5"><li>Entrer la formule (on veut vérifier à partir de E5, et seulement la colonne E, donc $ avant la colonne) : <ul><li><code>=$E5&gt;=20000</code></li></ul></li><li>Définir le format (couleur rouge) et appliquer</li></ol><img src="'+p+'" alt="Résultat avec surbrillance rouge" class="img-bordered"><blockquote><p>La procédure est similaire pour la couleur verte.</p></blockquote>',40)])])}const E=l(m,[["render",g]]);export{k as __pageData,E as default};
